"""Bounded character-prefix-aware DataFrame column permutation search.

The implementation compares exactly two complete constructions: a global
length-weighted repetition order and one forced-leader order.  The forced
leader is selected from at most sixteen high-repetition columns using the
exact single-column sorted-LCP objective.  Merge and dependency constraints
are then repaired before whole-row serialized Trie reuse is measured.
"""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Reorder rows and columns while preserving all original cell values."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the latest row-specific column orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one scalar as scoring does, mapping scalar missing values to ''."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute an exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings) -> int:
        """Compute ideal character-Trie reuse from sorted adjacent row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column labels to their source positions."""
        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(str(name), []).append(i)
        return positions

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build connected, source-ordered blocks for requested column merges."""
        parent = list(range(width))

        def find(value):
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted(
            (sorted(group) for group in groups.values()),
            key=lambda group: group[0],
        )

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Return a preference-respecting topological order satisfying constraints."""
        positions = cls._positions(columns)
        edges = []
        seen = set()

        def add(left, right):
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                edges.append((left, right))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: i for i, column in enumerate(preference)}
        ready = [
            (rank.get(i, width + i), i)
            for i in range(width)
            if indegree[i] == 0
        ]
        heapq.heapify(ready)

        result = []
        while ready:
            _, node = heapq.heappop(ready)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(
                        ready,
                        (rank.get(nxt, width + nxt), nxt),
                    )

        if len(result) == width:
            return result
        return list(preference)

    @staticmethod
    def _stats(text):
        """Calculate length-weighted equality repetition statistics per column."""
        rows, width = text.shape
        result = []

        for col in range(width):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1

            pair = repeat = mass = 0
            for value, count in counts.items():
                length = len(value)
                pair += length * count * (count - 1)
                repeat += length * max(0, count - 1)
                mass += length * count
            result.append((pair, repeat, mass))

        return result

    @staticmethod
    def _serialize(text, order):
        """Serialize every source row using one repaired column order."""
        rows, _ = text.shape
        return [
            "".join(text[row, column] for column in order)
            for row in range(rows)
        ]

    @classmethod
    def _single_column_score(cls, text, column):
        """Measure exact sorted-LCP reuse of one candidate leading column."""
        return cls._score([text[row, column] for row in range(text.shape[0])])

    @staticmethod
    def _materialize(df, source, order, serialized):
        """Sort rows by serialized keys and emit valid per-row public orders."""
        row_order = sorted(
            range(len(serialized)),
            key=lambda row: (serialized[row], row),
        )

        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            for output_col, source_col in enumerate(order):
                values[output_row, output_col] = source[source_row, source_col]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate global and forced-leader constructions, then materialize the best."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)

        for col in range(width):
            text[:, col] = [
                self._cell_string(value)
                for value in source[:, col]
            ]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        global_order = [
            column
            for column, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        # The frontier is deliberately bounded.  Candidates are ranked by
        # the same pair-repetition heuristic used for the global proposal,
        # while the selected leader is determined by exact character reuse.
        frontier = global_order[: min(16, width)]
        leader = max(
            frontier,
            key=lambda column: (
                self._single_column_score(text, column),
                stats[column][0],
                stats[column][1],
                stats[column][2],
                -column,
            ),
        )

        forced_order = [leader]
        forced_order.extend(
            column for column in global_order if column != leader
        )

        best_score = -1
        best_order = None
        best_serialized = None

        for preference in (global_order, forced_order):
            repaired = self._repair(
                width,
                preference,
                columns,
                one_way_dep,
                blocks,
            )
            serialized = self._serialize(text, repaired)
            score = self._score(serialized)

            if score > best_score:
                best_score = score
                best_order = repaired
                best_serialized = serialized

        result, public_orders = self._materialize(
            df,
            source,
            best_order,
            best_serialized,
        )

        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

