        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            for output_col, source_col in enumerate(order):
                values[output_row, output_col] = source[source_row, source_col]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate global and forced-leader constructions, then materialize the best."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)

        for col in range(width):
            text[:, col] = [
                self._cell_string(value)
                for value in source[:, col]
            ]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        global_order = [
            column
            for column, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        # The frontier is deliberately bounded.  Candidates are ranked by
        # the same pair-repetition heuristic used for the global proposal,
        # while the selected leader is determined by exact character reuse.
        frontier = global_order[: min(16, width)]
        leader = max(
            frontier,
            key=lambda column: (
                self._single_column_score(text, column),
                stats[column][0],
                stats[column][1],
                stats[column][2],
                -column,
            ),
        )

        forced_order = [leader]
        forced_order.extend(
            column for column in global_order if column != leader
        )

        best_score = -1
        best_order = None
        best_serialized = None

        for preference in (global_order, forced_order):
            repaired = self._repair(
                width,
                preference,
                columns,
                one_way_dep,
                blocks,
            )
            serialized = self._serialize(text, repaired)
            score = self._score(serialized)

            if score > best_score:
                best_score = score
                best_order = repaired
                best_serialized = serialized

        result, public_orders = self._materialize(
            df,
            source,
            best_order,
            best_serialized,
        )

        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders
